param([string]$ProjectPath='C:\Projects\gympro-api',[string]$BackupRoot='C:\Projects\gympro-backups')
$ErrorActionPreference='Stop'
$original=Get-Location
$code=0
try {
 Set-Location -LiteralPath $ProjectPath
 $node=(Get-Command node.exe -ErrorAction Stop).Source
 if(-not(Test-Path '.\sql')){throw 'Project SQL directory missing.'}
 $report=Join-Path $BackupRoot ('completion-batch1b-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,6))
 New-Item -ItemType Directory -Path $report -Force | Out-Null
 $payload=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('')) | ConvertFrom-Json
 $utf8=New-Object Text.UTF8Encoding($false)
 foreach($item in $payload.PSObject.Properties){
  $target=Join-Path $ProjectPath $item.Name
  if((Test-Path $target) -and ([IO.File]::ReadAllText($target) -cne $item.Value)){throw "Existing inventory tool differs; retained: $($item.Name)"}
 }
 foreach($item in $payload.PSObject.Properties){
  $target=Join-Path $ProjectPath $item.Name
  New-Item -ItemType Directory -Path (Split-Path $target) -Force | Out-Null
  if(-not(Test-Path $target)){[IO.File]::WriteAllText($target,$item.Value,$utf8)}
 }
 Write-Host 'CHECK: Inventory tool tests (no database connection)' -ForegroundColor Cyan
 & $node --test '.\tools\migration-inventory\inventory.test.mjs'
 if($LASTEXITCODE -ne 0){throw 'Inventory self-tests failed.'}
 Write-Host 'CHECK: SQL source inventory' -ForegroundColor Cyan
 & $node '.\tools\migration-inventory\inventory.mjs' $ProjectPath $report
 if($LASTEXITCODE -ne 0){throw 'SQL inventory failed.'}
 $summary=Get-Content (Join-Path $report 'sql-inventory.json') -Raw | ConvertFrom-Json
 if($summary.inventoryCompleted -ne $true -or $summary.automaticExecutionAllowed -ne $false -or $summary.files.Count -lt 1){throw 'Inventory summary failed validation.'}
 $destination=Join-Path $ProjectPath 'docs\completion'
 New-Item -ItemType Directory -Path $destination -Force | Out-Null
 foreach($name in @('sql-inventory.json','sql-inventory.md')){
  $target=Join-Path $destination $name
  if(Test-Path $target){Copy-Item -LiteralPath $target -Destination (Join-Path $report ($name+'.before'))}
  Copy-Item -LiteralPath (Join-Path $report $name) -Destination $target -Force
 }
 $runnerTarget=Join-Path $ProjectPath 'scripts\completion-batch1b-inventory.ps1'
 if(Test-Path $runnerTarget){
  if([IO.File]::ReadAllText($runnerTarget) -cne [IO.File]::ReadAllText($PSCommandPath)){throw 'Existing inventory runner differs; retained. Inventory reports were generated successfully.'}
 } else {
  New-Item -ItemType Directory -Path (Split-Path $runnerTarget) -Force | Out-Null
  Copy-Item -LiteralPath $PSCommandPath -Destination $runnerTarget
 }
 Write-Host 'PASS: Batch 1B SQL inventory completed; 8 tool tests passed.' -ForegroundColor Green
 Write-Host ('SQL files inventoried: '+$summary.files.Count)
 Write-Host ('Core objects without static CREATE candidates: '+@($summary.prerequisiteEvidence | Where-Object {$_.staticCreateCandidates.Count -eq 0}).Count)
 Write-Host 'PENDING: Reviewed installation order, bootstrap DDL, migration ledger and clean-install verification.'
 Write-Host 'No SQL executed, database connection, authentication change, UI change or Git commit.'
 Write-Host "Reports: $report"
 Write-Host ('Send this file: '+(Join-Path $report 'sql-inventory.json'))
} catch {
 $code=1
 Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red
 if($report){Write-Host "Keep reports: $report"}
} finally {Set-Location $original}
exit $code
